record.field:
for company in records:
    if company.child_ids:
        try:
            # Step 1: Create transit warehouse for the company that just got children
            company.sudo()._create_transit_warehouse()

            # Step 2: Reconfigure the company's own warehouses.
            # Now that it has a transit warehouse, its own warehouses need
            # an "own transit" config added.
            has_real_wh = bool(env['stock.warehouse'].sudo().search([
                ('company_id', '=', company.id),
                ('is_transit_warehouse', '=', False),
            ], limit=1))
            if has_real_wh:
                company.sudo()._create_warehouse_transit_picking_types()

            # Step 3: Reconfigure ALL descendants.
            # _create_warehouse_transit_picking_types() walks ancestors, so
            # calling it on every descendant is idempotent for existing configs
            # and will add the new transit location config where missing.
            all_descendants = company.sudo()._get_all_descendants()
            for descendant in all_descendants:
                descendant_has_real_wh = bool(env['stock.warehouse'].sudo().search([
                    ('company_id', '=', descendant.id),
                    ('is_transit_warehouse', '=', False),
                ], limit=1))
                if descendant_has_real_wh:
                    descendant.sudo()._create_warehouse_transit_picking_types()

        except Exception as e:
            raise Exception("Error creating transit warehouse: %s" % str(e))

if records:
    try:
        records.sudo().automation_handle_company_name_change()
    except Exception as e:
        raise Exception("Transit automation error: %s" % str(e))

for warehouse in records:
    if warehouse.company_id:
        try:
            warehouse.company_id.sudo()._create_warehouse_transit_picking_types(warehouse=warehouse)
        except Exception as e:
            raise Exception("Error creating transit picking types for warehouse: %s" % str(e))

# Batch: find all transit picking pairs whose SRC picking is in this trigger batch
transit_pickings = env['transit.picking'].search([
    ('src_picking_id', 'in', records.ids)
])

if transit_pickings:
    transit_pickings.automation_handle_src_picking_done()

# Batch: find all transit picking pairs whose DEST picking is in this trigger batch
transit_pickings = env['transit.picking'].search([
    ('dest_picking_id', 'in', records.ids)
])

if transit_pickings:
    transit_pickings.automation_handle_dest_picking_done()

src_transit_pickings = env['transit.picking'].search([
    ('src_picking_id', 'in', records.ids)
])
dest_transit_pickings = env['transit.picking'].search([
    ('dest_picking_id', 'in', records.ids)
])

if src_transit_pickings or dest_transit_pickings:
    (src_transit_pickings | dest_transit_pickings).automation_handle_picking_cancelled(
        records.ids
    )

src_transit_pickings = env['transit.picking'].search([
    ('src_picking_id', 'in', records.ids)
])
dest_transit_pickings = env['transit.picking'].search([
    ('dest_picking_id', 'in', records.ids)
])

if src_transit_pickings or dest_transit_pickings:
    (src_transit_pickings | dest_transit_pickings).automation_handle_picking_deleted(
        records.ids
    )
